-- definition globale_veraenderung@1.0.0 sha256:209c3d46bb84f872b0cbf1a5d86c4af6ad8a08fc512ec41789183eca45e52228
insert into public.questionnaire_definitions (instrument_id, version, definition) values
  ('globale_veraenderung', '1.0.0', '{"meta":{"id":"globale_veraenderung","version":"1.0.0","name_de":"Globale Veränderungsfrage","name_en":"Global Rating of Change","region":"uebergreifend","konstrukt":"selbst eingeschätzte Veränderung seit Behandlungsbeginn","ausgefuellt_von":"patient","sprache":"de","prioritaet":"a","quelle":{"literatur":"Kamper SJ, Maher CG, Mackay G. Global rating of change scales: a review of strengths and weaknesses and considerations for design. Journal of Manual & Manipulative Therapy 2009;17(3):163–170","praxisvorgabe":"Wortlaut als Vorgabe der Praxis freigegeben von Jannes am 2026-09-28/29 (ANN-099)","validierung":"Praxisvorgabe, keine validierte deutsche Fassung"},"lizenzstatus":{"status":"freigegeben","begruendung":"Frei verwendbar, keine Lizenz (IDEA-OUT-001, IDEA-OUT-004).","stand":"2026-09-25"},"aktiv":true,"vergleichbar_mit":["0.1.0"]},"items":[{"id":"veraenderung","nummer":1,"text":"Wie hat sich Ihr Zustand seit Beginn der Behandlung verändert?","typ":"einzelauswahl","optionen":[{"label":"sehr viel schlechter","wert":-3},{"label":"viel schlechter","wert":-2},{"label":"etwas schlechter","wert":-1},{"label":"unverändert","wert":0},{"label":"etwas besser","wert":1},{"label":"viel besser","wert":2},{"label":"sehr viel besser","wert":3}]}],"scoring":{"regel_wortlaut":"Die gewählte Antwort ist der Wert, von -3 (sehr viel schlechter) bis +3 (sehr viel besser).","gesamt":{"formel":{"art":"einzelwert","item":"veraenderung"},"wertebereich":{"min":-3,"max":3}},"subskalen":[],"richtung":"hoch_ist_besser","missing_value_regel":"Ohne Antwort kein Wert."},"interpretation":{"cutoffs":null,"mcid":null,"mdc":null},"referenzfaelle":[{"bezeichnung":"viel besser","antworten":{"veraenderung":2},"erwartet":{"gesamt":2}},{"bezeichnung":"sehr viel schlechter","antworten":{"veraenderung":-3},"erwartet":{"gesamt":-3}}]}'::jsonb);

-- definition nrs_schmerz@1.0.0 sha256:f02359f55295294732bc7df106f69892a0796184ee222f62251818701a0a1ca2
insert into public.questionnaire_definitions (instrument_id, version, definition) values
  ('nrs_schmerz', '1.0.0', '{"meta":{"id":"nrs_schmerz","version":"1.0.0","name_de":"Numerische Rating-Skala Schmerz (NRS)","name_en":"Numeric Pain Rating Scale","region":"uebergreifend","konstrukt":"Schmerzintensität","ausgefuellt_von":"patient","sprache":"de","prioritaet":"a","quelle":{"literatur":"Hawker GA, Mian S, Kendzerska T, French M. Measures of adult pain. Arthritis Care & Research 2011;63(S11):S240–S252","praxisvorgabe":"Wortlaut als Vorgabe der Praxis freigegeben von Jannes am 2026-09-28/29 (ANN-099)","validierung":"Praxisvorgabe, keine validierte deutsche Fassung"},"lizenzstatus":{"status":"freigegeben","begruendung":"Frei verwendbar, keine Lizenz (IDEA-OUT-001, „Pragmatischer Einstieg\").","stand":"2026-09-25"},"aktiv":true,"vergleichbar_mit":["0.1.0"]},"items":[{"id":"schmerz_aktuell","nummer":1,"text":"Wie stark sind Ihre Schmerzen im Moment?","typ":"skala","skala":{"min":0,"max":10},"anker":{"min":"keine Schmerzen","max":"stärkste vorstellbare Schmerzen"}}],"scoring":{"regel_wortlaut":"Der angekreuzte Wert ist der Wert.","gesamt":{"formel":{"art":"einzelwert","item":"schmerz_aktuell"},"wertebereich":{"min":0,"max":10}},"subskalen":[],"richtung":"hoch_ist_schlechter","missing_value_regel":"Ohne Antwort kein Wert."},"interpretation":{"cutoffs":null,"mcid":null,"mdc":null},"referenzfaelle":[{"bezeichnung":"Wert 7","antworten":{"schmerz_aktuell":7},"erwartet":{"gesamt":7}},{"bezeichnung":"ohne Antwort","antworten":{},"erwartet":{"gesamt":null}}]}'::jsonb);
